// <model-source> — the composition-as-source-for-3D descriptor for
// <model-view>. The 3D analogue of <video-source> / <source>: a typed slot
// of metadata the parent <model-view> reads to resolve what to render. Renders
// nothing itself.
//
//   <model-view><model-source src="model.glb"></model-source></model-view>
//
// THE COMPOSITION-AS-SOURCE MOMENT (text → geometry): the `code` form carries a
// scene SOURCE (an OpenSCAD-like / minimal CSG scene spec) that compiles to a GLB
// in-browser via **Manifold** wasm (manifold-3d, lazy CDN ESM) and feeds the
// resulting blob URL to the parent — exactly the way <video-source> inlines a
// wavelet composition. The source IS the model: edit the text, recompile, the
// viewer updates; the GLB never has to be shipped.
//
//   <model-view camera-controls>
//     <model-source code="cube(20); sphere(12);"></model-source>
//   </model-view>
//
// STATUS — STUBBED (directive: "if Manifold is heavy, scope the viewer solid first
// and STUB model-source with a clear note"). The descriptor contract + the
// parent wiring + the lazy single-flight Manifold loader (overridable via
// window.__WB_MANIFOLD__) are REAL and shipped. The scene-spec → Manifold-mesh
// COMPILER (`_compileScene`) is the only deferred piece: today it parses the spec
// and reports that the kernel binding is pending, surfacing a clear status on the
// parent rather than rendering a wrong model. Wiring a real Manifold build is a
// follow-up (tracked for merge); the seam below is where it lands — `compile()`
// already returns the {url} the parent consumes, so flipping the stub to live is
// a localized change with no parent churn.

import { WbElement, html, css, define } from "../../core/element.js";

const DEFAULT_MANIFOLD_SRC = "https://esm.sh/manifold-3d@3.0.0";

// Single-flight lazy import of the Manifold wasm module. Overridable via
// window.__WB_MANIFOLD__ (tests / offline hosts / a host that pre-bundled it).
let _manifoldLoad = null;
export function loadManifold(rawSrc = DEFAULT_MANIFOLD_SRC) {
  if (typeof window !== "undefined" && window.__WB_MANIFOLD__) {
    return Promise.resolve(window.__WB_MANIFOLD__);
  }
  let src = rawSrc;
  try {
    if (typeof document !== "undefined") src = new URL(rawSrc, document.baseURI).href;
  } catch { /* keep rawSrc */ }
  if (!_manifoldLoad) {
    _manifoldLoad = import(/* @vite-ignore */ src).then(
      (m) => m,
      (e) => { _manifoldLoad = null; throw e; },
    );
  }
  return _manifoldLoad;
}

export class WorkModelSource extends WbElement {
  static props = ["src", "code", "manifold-src", "type"];
  // metadata only — no visible rendering.
  static styles = css`:host { display: none; }`;

  /** The source descriptor the parent <model-view> reads. */
  get descriptor() {
    return {
      src: this.attr("src"),
      code: this.attr("code"),
      type: this.attr("type", this.attr("code") ? "scene/manifold" : "model/gltf-binary"),
    };
  }

  /**
   * Compile this source to something <model-view> can render.
   *  • `src` form  → returns { url } directly (a GLB/STL URL, no compile).
   *  • `code` form → compiles the scene spec to a GLB blob URL via Manifold.
   *
   * STUB: the `code` path loads the Manifold module + parses the spec, but the
   * spec→mesh kernel binding is pending — it resolves with { pending:true, note }
   * so the parent shows a clear status instead of a wrong model. The `src` path is
   * fully live.
   */
  async compile() {
    const code = this.attr("code");
    if (!code) return { url: this.attr("src") || null };

    let manifold = null;
    try { manifold = await loadManifold(this.attr("manifold-src", DEFAULT_MANIFOLD_SRC)); }
    catch (e) { return { pending: true, note: `Manifold unavailable: ${e?.message || e}` }; }

    const parsed = parseScene(code);
    // ── deferred kernel binding ────────────────────────────────────────────
    // Where the real build lands: turn `parsed` ops into Manifold primitives
    // (manifold.cube/sphere/...), boolean-compose, mesh → GLB via a GLTF
    // exporter, URL.createObjectURL(blob). Returns { url } with no parent churn.
    void manifold;
    return {
      pending: true,
      ops: parsed,
      note: `model-source: parsed ${parsed.length} op(s); Manifold spec→GLB compile is stubbed (kernel binding pending). Use src= for a ready model.`,
    };
  }

  attributeChangedCallback(name, oldV, newV) {
    super.attributeChangedCallback?.(name, oldV, newV);
    if (this.isConnected && oldV !== newV) {
      this.closest("model-view")?._resolveSource?.();
    }
  }

  render() { return html``; }
}

/** Minimal OpenSCAD-like scene parser: `cube(20); sphere(12);` → [{op,args}]. */
function parseScene(code) {
  const ops = [];
  for (const stmt of String(code).split(";")) {
    const m = /^\s*([a-z_]+)\s*\(([^)]*)\)\s*$/i.exec(stmt);
    if (!m) continue;
    const args = m[2].split(",").map((s) => s.trim()).filter(Boolean).map(Number);
    ops.push({ op: m[1].toLowerCase(), args });
  }
  return ops;
}

define("model-source", WorkModelSource);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}
